sys_ui_action.script:
try{
	// Recalculate the ingredient cost
	const ingToGoodGR = new GlideRecord("x_1128327_cake_ingredients_to_goods");
	ingToGoodGR.addQuery("good", current.getValue("sys_id"));
	ingToGoodGR.query();

	let ingredientCost = 0;
	while (ingToGoodGR.next()) {
		const ingGR = ingToGoodGR.ingredient.getRefRecord();
		const ingCost = parseFloat(ingGR.getValue("price"));
		const qty = parseFloat(ingToGoodGR.getValue("quantity"));
		ingredientCost += ingCost * qty;
	}
	current.ingredient_cost = ingredientCost.toFixed(2);

	// Recalculate the preparation cost
	let prepCost = 0;
	const settingGR = new GlideRecord("x_1128327_cake_settings");
	if (settingGR.get("name", "Hourly rate")) {
		const hourlyRate = parseFloat(settingGR.getValue("value"));

		// Get the hours and minutes
		const prepTime = current.getValue("preparation_time");
		const durationParts = prepTime.split(" ")[1].split(":");
		const hours = parseInt(durationParts[0]);
		const minutes = parseInt(durationParts[1]);
		const totalHours = hours + (minutes/60);

		prepCost = totalHours * hourlyRate;
		current.preparation_cost = prepCost.toFixed(2);
	}

	// Recalculate the suggested price
	current.suggested_price = (ingredientCost + prepCost).toFixed(2);
	current.update();
	action.setRedirectURL(current);
} catch (e){
	gs.error(e);
}
